<?php
declare(strict_types=1);
namespace App\Controller\Shop;
use App\Cms\{CmsPageResolver,CmsSlug}; use App\Entity\Cms\CmsRedirect; use Doctrine\ORM\EntityManagerInterface; use Sylius\Component\Channel\Context\ChannelContextInterface; use Sylius\Component\Locale\Context\LocaleContextInterface; use Symfony\Bundle\FrameworkBundle\Controller\AbstractController; use Symfony\Component\HttpFoundation\{RedirectResponse,Response}; use Symfony\Component\Routing\Attribute\Route;
final class CmsPageController extends AbstractController { public function __construct(private readonly CmsPageResolver $resolver,private readonly EntityManagerInterface $em,private readonly ChannelContextInterface $channels,private readonly LocaleContextInterface $locales){} #[Route('/{cmsPath}',name:'cardnext_shop_cms_page',requirements:['cmsPath'=>'(?!admin(?:/|$)|api(?:/|$)|account(?:/|$)|cart(?:/|$)|checkout(?:/|$)|login$|register$|search(?:/|$)|configurator(?:/|$)|sitemap\.xml$).+'],methods:['GET'],priority:-255)] public function __invoke(string $cmsPath):Response { $page=$this->resolver->resolve($cmsPath);if($page){$locale=$this->locales->getLocaleCode();return $this->render('shop/cms/show.html.twig',['page'=>$page,'translation'=>$page->getTranslation($locale),'locale'=>$locale]);} $source=CmsSlug::normalize($cmsPath);$redirect=$this->em->getRepository(CmsRedirect::class)->findOneBy(['channel'=>$this->channels->getChannel(),'locale'=>$this->locales->getLocaleCode(),'sourcePath'=>$source]);if($redirect){$target=$redirect->getTargetPath()??$redirect->getTargetPage()?->getTranslation($this->locales->getLocaleCode())?->getSlug();if($target&&$target!==$source&&$this->resolver->resolve($target))return new RedirectResponse('/'.$target,$redirect->getStatusCode());} throw $this->createNotFoundException();} }
